'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n||0).toLocaleString('pt-BR'),today=()=>new Date().toLocaleDateString('sv-SE'),date=v=>v?new Date(v+'T12:00:00').toLocaleDateString('pt-BR'):'Não definida';
const machines=['MÁQUINAS 8','MÁQUINAS 15','SOLDA PONTO','MÁQUINA 40','MÁQUINA 45.1','MÁQUINA 60','AUTOMÁTICAS'],statuses=['A conferir','Aguardando','Programado','Em produção','Pausado','Concluído','Cancelado'];
let db;try{db=JSON.parse(localStorage.getItem('pcp-weslei-v1'))}catch{}if(!db)db={orders:structuredClone(SEED),logs:[],capacity:Object.fromEntries(machines.map(m=>[m,8]))};
let view='Visão geral',q='',mf='',sf='',page=0;
function save(){try{localStorage.setItem('pcp-weslei-v1',JSON.stringify(db))}catch{alert('Não foi possível salvar. Exporte um backup antes de continuar.');throw Error('Falha ao salvar')}render()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
function active(o){return !['Concluído','Cancelado'].includes(o.status)}function late(o){return active(o)&&o.due&&o.due<today()}function produced(o){return db.logs.filter(l=>l.order===o.id).reduce((s,l)=>s+l.good,0)}function remain(o){return Math.max(0,o.planned-produced(o))}function hours(o){return remain(o)/(o.rate||1)+(o.setup||0)}
const menus=[['◫','Visão geral'],['▤','Pedidos'],['▦','Planejamento'],['◷','Apontamentos'],['⚙','Capacidade'],['↗','Relatórios'],['⊞','Dados da planilha']];
$('#nav').innerHTML=menus.map(([i,n])=>`<button data-view="${n}"><span>${i}</span>${n}</button>`).join('');$('#nav').onclick=e=>{let b=e.target.closest('button');if(b){view=b.dataset.view;q=mf=sf='';page=0;render()}};
function badge(o){return `<span class="badge ${late(o)?'bad':o.status==='Concluído'?'good':o.status==='Em produção'?'blue':''}">${late(o)?'Prazo vencido · ':''}${esc(o.status)}</span>`}
function filtered(){return db.orders.filter(o=>(!q||[o.number,o.code,o.product,o.client].join(' ').toLowerCase().includes(q.toLowerCase()))&&(!mf||o.machine===mf)&&(!sf||o.status===sf))}
function tools(){return `<div class="toolbar"><input aria-label="Pesquisar pedidos" placeholder="⌕ Buscar pedido, cliente ou produto..." value="${esc(q)}" oninput="q=this.value;page=0;refreshTable()"><select aria-label="Filtrar centro" onchange="mf=this.value;page=0;refreshTable()"><option value="">Todos os centros</option>${machines.map(m=>`<option ${mf===m?'selected':''}>${m}</option>`).join('')}</select><select aria-label="Filtrar status" onchange="sf=this.value;page=0;refreshTable()"><option value="">Todos os status</option>${statuses.map(s=>`<option ${sf===s?'selected':''}>${s}</option>`).join('')}</select><button onclick="exportCSV()">Exportar CSV</button></div>`}
function table(rows,limit=15){let start=page*limit,part=rows.slice(start,start+limit);return `<div class="tablewrap"><table><thead><tr><th>PEDIDO / PRODUTO</th><th>CLIENTE</th><th>CENTRO</th><th>ENTREGA</th><th>PREVISTO / SALDO</th><th>SITUAÇÃO</th><th>AÇÕES</th></tr></thead><tbody>${part.map(o=>`<tr><td><strong>${esc(o.number||'Sem nº')} · ${esc(o.code)}</strong><small title="${esc(o.product)}">${esc(o.product)}</small></td><td><strong>${esc(o.client)}</strong></td><td>${esc(o.machine||'A definir')}</td><td>${date(o.due)}</td><td>${fmt(o.planned)}<small>Saldo: ${fmt(remain(o))} un.</small></td><td>${badge(o)}</td><td><button class="tiny" onclick="edit('${o.id}')">Abrir</button> <button class="tiny" onclick="point('${o.id}')">＋ Produção</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nenhum pedido encontrado.</td></tr>'}</tbody></table></div><div class="pagination">${rows.length} itens <span style="margin-left:auto">Página ${page+1} de ${Math.max(1,Math.ceil(rows.length/limit))}</span><button class="tiny" ${page===0?'disabled':''} onclick="page--;refreshTable()">←</button><button class="tiny" ${start+limit>=rows.length?'disabled':''} onclick="page++;refreshTable()">→</button></div>`}
function refreshTable(){ $('#table').innerHTML=table(filtered()) }
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#title').textContent=view;$('#today').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});let open=db.orders.filter(active),good=db.logs.reduce((s,l)=>s+l.good,0),loss=db.logs.reduce((s,l)=>s+l.loss,0);$('#metrics').innerHTML=[['Pedidos em carteira',fmt(open.length),'Itens ainda não concluídos'],['Saldo a produzir',fmt(open.reduce((s,o)=>s+remain(o),0)),'Unidades previstas pendentes'],['Prazos vencidos',fmt(db.orders.filter(late).length),'Revise as datas e prioridades'],['Produção apontada',fmt(good),`${fmt(loss)} unidades de perda registradas`]].map(x=>`<div class="metric"><label>${x[0]}</label><b>${x[1]}</b><small>${x[2]}</small></div>`).join('');let c=$('#content');
if(view==='Visão geral'){let urgent=[...open].sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,6);c.innerHTML=`<div class="two"><div class="panel"><div class="panelhead"><div><h3>Carga por centro de produção</h3><small>Saldo em unidades · volumes de produtos diferentes não medem capacidade</small></div><span class="badge good">CARTEIRA</span></div>${machines.map(m=>{let list=open.filter(o=>o.machine===m),qty=list.reduce((s,o)=>s+remain(o),0),max=Math.max(1,...machines.map(k=>open.filter(o=>o.machine===k).reduce((s,o)=>s+remain(o),0)));return `<div class="machine"><div><span>${m} <small>· ${list.length} itens</small></span><b>${fmt(qty)} un.</b></div><section class="track"><i style="width:${qty/max*100}%"></i></section></div>`}).join('')}</div><div class="panel"><div class="panelhead"><div><h3>Radar do planejamento</h3><small>Pontos que precisam da sua atenção</small></div>◎</div>${[[db.orders.filter(o=>o.status==='A conferir').length,'itens aguardam validação da importação'],[open.filter(o=>!o.start).length,'itens sem data de produção'],[open.filter(o=>!o.rate).length,'itens sem produtividade cadastrada'],[open.filter(o=>!o.planned).length,'itens sem quantidade prevista']].map(([n,t])=>`<div class="machine"><div><b>${fmt(n)}</b><span>${t}</span></div></div>`).join('')}<div class="notice">Comece conferindo os pedidos importados. Depois, defina centro, data de produção e produtividade para analisar a carga em horas.</div><div style="padding:20px"><button onclick="view='Pedidos';sf='A conferir';render()">Conferir carteira →</button></div></div></div><div class="panel"><div class="panelhead"><div><h3>Próximas entregas</h3><small>Pedidos abertos ordenados pela data de entrega</small></div><button class="tiny" onclick="view='Pedidos';render()">Ver todos →</button></div>${table(urgent,6)}</div>`}
else if(view==='Pedidos')c.innerHTML=`<div class="panel"><div class="panelhead"><div><h3>Carteira de pedidos</h3><small>Cadastre, programe e acompanhe cada item de produção</small></div><button class="tiny" onclick="sortDue()">Ordenar por entrega</button></div>${tools()}<div id="table">${table(filtered())}</div></div>`;
else if(view==='Planejamento'){c.innerHTML=`<div class="panel"><div class="panelhead"><div><h3>Quadro da produção</h3><small>Abra um item para definir data, sequência, recurso e situação</small></div><button onclick="window.print()">Imprimir</button></div><div class="notice">Carga em horas depende de produtividade (un./h) e setup informados. Datas e sequência são definidas pelo analista; o sistema sinaliza excesso de capacidade diária.</div></div><div class="kanban">${['A conferir','Aguardando','Programado','Em produção'].map(s=>{let list=open.filter(o=>o.status===s).sort((a,b)=>(a.start||'9999').localeCompare(b.start||'9999')||a.sequence-b.sequence);return `<div class="column"><h3>${s} <span class="badge">${list.length}</span></h3>${list.map(o=>`<div class="card"><span class="badge">${esc(o.machine||'A definir')}</span><b>${esc(o.code)} · ${esc(o.product)}</b><p>${esc(o.client)}</p><p>Produção: ${date(o.start)} · Seq. ${o.sequence||'—'}</p><p>Saldo ${fmt(remain(o))} un. · ${o.rate?hours(o).toFixed(1)+' h':'Produtividade pendente'}</p>${badge(o)}<p><button class="tiny" onclick="edit('${o.id}')">Programar</button> <button class="tiny" onclick="point('${o.id}')">Apontar</button></p></div>`).join('')||'<p class="empty">Sem itens</p>'}</div>`}).join('')}</div><div class="panel" style="margin-top:20px"><div class="panelhead"><h3>Itens pausados</h3></div>${table(open.filter(o=>o.status==='Pausado'),15)}</div>`}
else if(view==='Apontamentos')c.innerHTML=`<div class="panel"><div class="panelhead"><div><h3>Diário da produção</h3><small>Quantidades boas, perdas, horas e operador por lançamento</small></div><button class="primary" onclick="point()">＋ Apontar produção</button></div><div class="tablewrap"><table><thead><tr><th>DATA</th><th>PEDIDO / PRODUTO</th><th>BOAS</th><th>PERDAS</th><th>HORAS</th><th>OPERADOR / OBSERVAÇÃO</th><th>AÇÃO</th></tr></thead><tbody>${[...db.logs].reverse().map(l=>{let o=db.orders.find(o=>o.id===l.order);return `<tr><td>${date(l.date)}</td><td>${esc(o?.code)}<small>${esc(o?.product)}</small></td><td>${fmt(l.good)}</td><td>${fmt(l.loss)}</td><td>${fmt(l.hours)}</td><td>${esc(l.operator)}<small>${esc(l.note)}</small></td><td><button class="tiny danger" onclick="undo('${l.id}')">Estornar</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">Nenhum apontamento registrado. Selecione um pedido para começar.</td></tr>'}</tbody></table></div></div>`;
else if(view==='Capacidade'){let groups={};open.filter(o=>o.start).forEach(o=>{let k=o.start+'|'+o.machine;(groups[k]??=[]).push(o)});c.innerHTML=`<div class="panel"><div class="panelhead"><div><h3>Capacidade disponível por dia</h3><small>Horas líquidas por centro · configure conforme turnos e disponibilidade</small></div></div><div style="padding:22px"><form id="caps" class="formgrid">${machines.map(m=>`<label>${m}<input type="number" name="${m}" min="0.1" step="0.1" required value="${db.capacity[m]}"></label>`).join('')}<button class="primary">Salvar capacidade</button></form></div></div><div class="panel"><div class="panelhead"><h3>Carga programada por dia e centro</h3></div><div class="tablewrap"><table><thead><tr><th>DATA</th><th>CENTRO</th><th>ITENS</th><th>CARGA ESTIMADA</th><th>DISPONÍVEL</th><th>SITUAÇÃO</th></tr></thead><tbody>${Object.entries(groups).sort().map(([k,list])=>{let [d,m]=k.split('|'),h=list.filter(o=>o.rate).reduce((s,o)=>s+hours(o),0),missing=list.some(o=>!o.rate),cap=db.capacity[m]||0;return `<tr><td>${date(d)}</td><td>${esc(m)}</td><td>${list.length}</td><td>${h.toFixed(1)} h${missing?' + pendências':''}</td><td>${cap} h</td><td><span class="badge ${h>cap?'bad':missing?'':'good'}">${h>cap?'Sobrecarga':missing?'Carga incompleta':'Dentro da capacidade'}</span></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Defina a data de produção nos pedidos para visualizar a carga.</td></tr>'}</tbody></table></div><div class="notice">A carga inteira do saldo é atribuída à data de produção informada. Divida lotes em itens separados quando a produção ocupar vários dias. Não considera sequenciamento automático, feriados ou dependências de componentes.</div></div>`;$('#caps').onsubmit=e=>{e.preventDefault();db.capacity=Object.fromEntries(machines.map(m=>[m,+new FormData(e.target).get(m)]));save();toast('Capacidade atualizada')}}
else if(view==='Relatórios')c.innerHTML=`<div class="panel"><div class="panelhead"><div><h3>Resultados e exportações</h3><small>Relatórios com os dados atuais do seu navegador</small></div><div class="actions"><button onclick="exportCSV()">Carteira CSV</button><button onclick="exportLogs()">Apontamentos CSV</button><button onclick="window.print()">Imprimir</button></div></div><div class="tablewrap"><table><thead><tr><th>CENTRO</th><th>PREVISTO ATIVO</th><th>BOAS (TODOS)</th><th>PERDAS (TODOS)</th><th>SALDO ATIVO</th><th>REFUGO</th></tr></thead><tbody>${machines.map(m=>{let orders=db.orders.filter(o=>o.machine===m),ids=new Set(orders.map(o=>o.id)),ls=db.logs.filter(l=>ids.has(l.order)),g=ls.reduce((s,l)=>s+l.good,0),p=ls.reduce((s,l)=>s+l.loss,0);return `<tr><td>${m}</td><td>${fmt(orders.filter(active).reduce((s,o)=>s+o.planned,0))}</td><td>${fmt(g)}</td><td>${fmt(p)}</td><td>${fmt(orders.filter(active).reduce((s,o)=>s+remain(o),0))}</td><td>${g+p?(p/(g+p)*100).toFixed(2)+'%':'—'}</td></tr>`}).join('')}</tbody></table></div></div>`;
else c.innerHTML=`<div class="panel"><div class="panelhead"><div><h3>Origem, segurança dos dados e backup</h3><small>Somente as sete abas não ocultas foram consideradas</small></div></div><div style="padding:24px;line-height:1.8"><p>Importação inicial: <b>${SEED.length} itens consolidados</b>. Registros idênticos entre abas foram unidos; as origens continuam nos detalhes. O centro inicial considera a primeira ocorrência consolidada e deve ser conferido. Linhas filtradas das abas visíveis também foram consideradas para preservar a carteira.</p><p><b>Mapeamento:</b> PEDIDO → número; PEDIDO2 → quantidade do pedido; PREVISTO → quantidade planejada. As colunas originais ficam disponíveis nos detalhes. Campos vazios não foram convertidos em produção concluída.</p><p><b>Salvamento local:</b> os registros ficam neste navegador e dispositivo. Não há sincronização entre usuários. Exporte backups JSON para proteger e transferir os dados.</p><div class="actions"><button class="primary" onclick="backup()">Baixar backup JSON</button><button onclick="$('#restore').click()">Restaurar backup JSON</button><button onclick="help()">Guia de uso</button></div><input id="restore" type="file" accept=".json" hidden onchange="restore(this.files[0])"></div></div>`;
}
function sortDue(){db.orders.sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));page=0;save()}
function show(html){$('#modalbody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}function closeModal(){$('#modal').close()}
function field(label,key,value='',type='text',extra=''){return `<label>${label}<input name="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function edit(id){let o=db.orders.find(o=>o.id===id)||{id:crypto.randomUUID(),status:'Aguardando',priority:'Normal',planned:0,qty:0,machine:machines[0],setup:0,sequence:1};show(`<h2>${id?'Detalhes do pedido':'Novo pedido de produção'}</h2><p>Dados comerciais, roteiro e programação do item.</p><form id="orderForm"><div class="formgrid">${field('Número do pedido','number',o.number)}${field('Código do produto *','code',o.code,'text','required')}${field('Cliente *','client',o.client,'text','required')}${field('Descrição do produto *','product',o.product,'text','required')}${field('Quantidade do pedido','qty',o.qty,'number','min="0" required')}${field('Quantidade prevista *','planned',o.planned,'number','min="1" required')}${field('Data de entrega','due',o.due,'date')}${field('Data de produção','start',o.start,'date')}<label>Centro de produção<select name="machine">${machines.map(m=>`<option ${o.machine===m?'selected':''}>${m}</option>`).join('')}</select></label><label>Situação<select name="status">${statuses.map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Prioridade<select name="priority">${['Normal','Alta','Urgente'].map(s=>`<option ${o.priority===s?'selected':''}>${s}</option>`).join('')}</select></label>${field('Sequência na fila','sequence',o.sequence,'number','min="1"')}${field('Produtividade (unidades / hora)','rate',o.rate||'','number','min="0.01" step="0.01"')}${field('Setup (horas por lote)','setup',o.setup||0,'number','min="0" step="0.01"')}${field('Responsável','owner',o.owner)}${field('Montagem / recurso','assembly',o.assembly)}${field('Dobra 1','bend',o.bend)}${field('Dobra 2','bend2',o.bend2)}${field('Dobra 3','bend3',o.bend3)}${field('Subproduto','subproduct',o.subproduct)}${field('Quantidade subproduto','subqty',o.subqty,'number','min="0"')}${[1,2,3].map(i=>field('Componente '+i,'component'+i,o['component'+i])+field('Quantidade componente '+i,'componentQty'+i,o['componentQty'+i]||0,'number','min="0"')).join('')}<label class="wide">Observações<textarea name="note" rows="2">${esc(o.note)}</textarea></label></div>${id?`<div class="history">Produção boa: ${fmt(produced(o))} un. · Saldo: ${fmt(remain(o))} un.<br>Origem: ${esc((o.origins||[]).join(' · ')||'Cadastro manual')}${o.raw?'<details><summary>Colunas originais da planilha</summary><pre>'+esc(JSON.stringify(o.raw,null,2))+'</pre></details>':''}</div>`:''}<div class="formactions" style="margin-top:20px">${id?`<button type="button" class="danger" onclick="removeOrder('${o.id}')">Excluir</button><button type="button" onclick="printOrder('${o.id}')">Imprimir OP</button>`:''}<button type="button" onclick="closeModal()">Cancelar</button><button class="primary">Salvar pedido</button></div></form>`);$('#orderForm').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));for(let k of ['qty','planned','sequence','setup','rate','subqty','componentQty1','componentQty2','componentQty3'])data[k]=+data[k]||0;if(data.planned<produced(o))return alert('O previsto não pode ser menor que a produção boa já apontada.');if(data.start&&data.due&&data.start>data.due&&!confirm('Produção programada após a entrega. Deseja manter?'))return;if(data.status==='Programado'&&!data.start)return alert('Informe a data de produção.');if(data.status==='Concluído'&&produced(o)<data.planned)return alert('Para concluir, registre a produção boa até atingir o previsto.');Object.assign(o,data);if(!id)db.orders.push(o);save();closeModal();toast('Pedido salvo')};}
function point(id){let eligible=db.orders.filter(o=>!['Concluído','Cancelado'].includes(o.status));if(!eligible.length)return toast('Não há pedidos abertos para apontar.');show(`<h2>Apontar produção</h2><p>Registre somente a quantidade produzida neste lançamento.</p><form id="pointForm"><div class="formgrid"><label class="wide">Pedido / produto<select name="order">${eligible.map(o=>`<option value="${o.id}" ${id===o.id?'selected':''}>${esc(o.number||'Sem nº')} · ${esc(o.code)} · ${esc(o.product)} | Saldo ${fmt(remain(o))}</option>`).join('')}</select></label>${field('Data *','date',today(),'date','required')}${field('Quantidade boa *','good','','number','min="0" step="1" required')}${field('Perdas / refugo *','loss',0,'number','min="0" step="1" required')}${field('Horas trabalhadas *','hours','','number','min="0.01" step="0.01" required')}${field('Operador *','operator','','text','required')}<label class="wide">Observação / motivo das perdas<textarea name="note"></textarea></label></div><div class="formactions"><button type="button" onclick="closeModal()">Cancelar</button><button class="primary">Registrar produção</button></div></form>`);$('#pointForm').onsubmit=e=>{e.preventDefault();let l=Object.fromEntries(new FormData(e.target));['good','loss','hours'].forEach(k=>l[k]=+l[k]);let o=db.orders.find(o=>o.id===l.order);if(l.good+l.loss<=0)return alert('Informe quantidade boa ou perdas.');if(l.date>today())return alert('O apontamento não pode ter data futura.');if(l.good>remain(o))return alert('A quantidade boa excede o saldo. Revise o previsto no pedido.');if(l.loss&&!l.note.trim())return alert('Informe o motivo das perdas.');l.id=crypto.randomUUID();db.logs.push(l);o.status=remain(o)===0?'Concluído':'Em produção';save();closeModal();toast('Produção registrada e saldo atualizado')};}
function removeOrder(id){if(db.logs.some(l=>l.order===id))return alert('Este pedido possui apontamentos. Estorne-os antes de excluir ou use o status Cancelado.');if(confirm('Excluir definitivamente este item?')){db.orders=db.orders.filter(o=>o.id!==id);save();closeModal();toast('Item excluído')}}
function undo(id){if(!confirm('Estornar este apontamento? O saldo será recomposto.'))return;let l=db.logs.find(l=>l.id===id),o=db.orders.find(o=>o.id===l.order);db.logs=db.logs.filter(l=>l.id!==id);if(o.status==='Concluído')o.status='Em produção';save();toast('Apontamento estornado')}
function download(name,text,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function backup(){download('pcp-backup-'+today()+'.json',JSON.stringify({version:1,...db},null,2),'application/json');toast('Backup exportado')}
async function restore(file){if(!file)return;try{let d=JSON.parse(await file.text());if(d.version!==1||!Array.isArray(d.orders)||!Array.isArray(d.logs)||!d.capacity)throw Error('Formato inválido');let ids=new Set;for(let o of d.orders){if(typeof o.id!=='string'||ids.has(o.id)||typeof o.code!=='string'||!statuses.includes(o.status)||!machines.includes(o.machine)||!Number.isFinite(o.planned)||o.planned<0)throw Error('Pedido inválido');ids.add(o.id);for(let key of ['due','start'])if(o[key]&&!/^\d{4}-\d{2}-\d{2}$/.test(o[key]))throw Error('Data inválida')}let logIds=new Set;for(let l of d.logs){if(!ids.has(l.order)||!l.id||logIds.has(l.id)||!['good','loss','hours'].every(k=>Number.isFinite(l[k])&&l[k]>=0))throw Error('Apontamento inválido');logIds.add(l.id)}if(!machines.every(m=>Number.isFinite(d.capacity[m])&&d.capacity[m]>0))throw Error('Capacidade inválida');if(!confirm('Substituir os dados atuais pelo backup? Exporte um backup atual antes de confirmar.'))return;db={orders:d.orders,logs:d.logs,capacity:d.capacity};page=0;save();toast('Backup restaurado')}catch(e){alert('Backup inválido: '+e.message)}}
function csv(name,rows){download(name,'\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function exportCSV(){csv('carteira-pcp.csv',[['Pedido','Código','Produto','Cliente','Centro','Entrega','Produção','Qtd pedido','Previsto','Boas','Saldo','Status','Prioridade','Un/h','Setup h','Observação'],...filtered().map(o=>[o.number,o.code,o.product,o.client,o.machine,o.due,o.start,o.qty,o.planned,produced(o),remain(o),o.status,o.priority,o.rate,o.setup,o.note])])}
function exportLogs(){csv('apontamentos-pcp.csv',[['Data','Código','Pedido','Boas','Perdas','Horas','Operador','Observação'],...db.logs.map(l=>{let o=db.orders.find(o=>o.id===l.order);return[l.date,o.code,o.number,l.good,l.loss,l.hours,l.operator,l.note]})])}
function printOrder(id){let o=db.orders.find(o=>o.id===id);show(`<h2>Ordem de produção · ${esc(o.number||o.code)}</h2><p>${esc(o.client)}</p><div class="formgrid">${[['Código',o.code],['Produto',o.product],['Centro',o.machine],['Data de produção',date(o.start)],['Entrega',date(o.due)],['Previsto',fmt(o.planned)],['Saldo',fmt(remain(o))],['Montagem',o.assembly],['Dobras',[o.bend,o.bend2,o.bend3].filter(Boolean).join(' → ')],['Responsável',o.owner],['Componentes',[1,2,3].filter(i=>o['component'+i]).map(i=>o['component'+i]+' × '+o['componentQty'+i]).join('; ')],['Observação',o.note]].map(([k,v])=>`<label>${k}<b>${esc(v||'—')}</b></label>`).join('')}</div><p>Operador: ____________________ Conferência: ____________________</p><div class="formactions"><button onclick="closeModal()">Fechar</button><button onclick="window.print()">Imprimir OP</button></div>`)}
function help(){show('<h2>Seu fluxo de trabalho no PCP</h2><p>1. Em Pedidos, confira os registros importados e as quantidades.</p><p>2. Cadastre novos itens com cliente, produto, previsto e prazo.</p><p>3. Defina centro, data, sequência, produtividade e setup. Use Programado para liberar à fila.</p><p>4. Em Capacidade, ajuste horas líquidas por centro e revise sobrecargas diárias.</p><p>5. Registre produção boa, perdas e horas em Apontamentos. O saldo diminui com peças boas; ao atingir o previsto, o pedido é concluído.</p><p>6. Use Pausado para bloqueios e informe o motivo nas observações. Componentes e dobras são controles descritivos: o consumo de estoque não é automático.</p><p>7. Exporte relatórios CSV e um backup JSON ao final de cada dia. Guarde o backup fora deste navegador.</p><div class="formactions"><button class="primary" onclick="closeModal()">Entendi</button></div>')}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});render();
